it('reads a Thread Message with threadRef and ignores an extra taskRef; projectRef reads the Main stream', async () => {
  const team = await boot()

  const threadMessage = await call('team_thread', { action: 'message', threadRef: team.firstThread, taskRef: team.secondTask, messageRef: team.first.message.messageRef }, team.peer.agent)
  expect(threadMessage).toMatchObject({ kind: 'message', message: { messageRef: team.first.message.messageRef } })

