11	export type SurfaceActivityBinding = ActivityIdentity & { readonly factDigest: string }
12	
13	export type TeamMessageSurface = {
14	  readonly textDigest: string
15	  readonly messages: readonly (MessageAddress & { readonly messageRef: string; readonly bodyDigest: string; readonly start?: number; readonly end?: number; readonly total?: number })[]
16	  readonly activities: readonly SurfaceActivityBinding[]
17	}
18	
19	type MessageAddress = { readonly threadRef: string; readonly projectRef?: never }
20	  | { readonly projectRef: string; readonly threadRef?: never }
21	
22	export type RenderedTeamMessage = MessageAddress & {
23	  readonly messageRef: string
24	  readonly body: string
25	  readonly part?: { readonly start: number; readonly end: number }
26	}
27	
28	const digest = (text: string): string => createHash('sha256').update(text).digest('hex')
29	
30	/** Bind rendered bodies or exact parts to the producer's complete output text. */
31	export function teamMessageSurface(text: string, messages: readonly RenderedTeamMessage[], activities: readonly ActivityFact[] = []) {
32	  const boundActivities = activities.map(fact => ({ ...activityIdentity(fact), factDigest: activityFactDigest(fact) }))
33	  return { textDigest: digest(text), messages: messages.map(message => ({
34	    ...(message.threadRef === undefined ? { projectRef: message.projectRef } : { threadRef: message.threadRef }),
35	    messageRef: message.messageRef, bodyDigest: digest(message.body),
36	    ...(message.part === undefined ? {} : { ...message.part, total: message.body.length }),
37	  })), activities: boundActivities }
38	}
39	
40	/** A live projection, not a read receipt. Cropped text cannot attest through retained metadata. */
41	export function visibleTeamSurface(agent: Pick<Agent, 'session'>): readonly TeamMessageSurface[] {
42	  const entries: TeamMessageSurface[] = []
43	  for (const sequence of agent.session.surface.nodes) {
44	    const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
45	    if (event === undefined) continue
46	    const message = agent.session.deriveEventMessage(event)
47	    if (message === null) continue
48	    let binding: unknown
49	    if (event.type === 'user/message' && message.role === 'user' && isAgentTeamSource(message.source) && message.source.form === 'notice') {
50	      binding = message.source.teamFacts
51	    } else if (event.type === 'tool/result' && message.role === 'tool' && !message.isError) {
52	      const ownCall = event.sourceEventSeqs?.some(sequence => {
53	        const call = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
54	        return call?.type === 'tool/call' && call.data.callId === message.toolCallId
55	          && (call.data.name === 'team_thread' || call.data.name === 'team_message' || call.data.name === 'team_task')
56	      })
57	      if (!ownCall) continue
58	      const meta = event.data.meta
59	      if (typeof meta !== 'object' || meta === null || Array.isArray(meta)) continue
60	      binding = meta['teamFacts']
61	    }
62	    const surface = surfaceOf(binding)
63	    if (surface === undefined || message.content.some(part => part.type !== 'text')) continue
64	    const text = message.content.flatMap(part => part.type === 'text' ? [part.text] : []).join('\n')
65	    if (digest(text) === surface.textDigest) entries.push(surface)
66	  }
67	  return entries
68	}
69	
70	function surfaceOf(value: unknown): TeamMessageSurface | undefined {
71	  if (typeof value !== 'object' || value === null) return undefined
72	  const surface = value as Partial<TeamMessageSurface> & { readonly activities?: unknown }
73	  if (typeof surface.textDigest !== 'string' || !Array.isArray(surface.messages)) return undefined
74	  if (!surface.messages.every(message => message !== null && typeof message === 'object'
75	    && ((typeof message.threadRef === 'string' && message.projectRef === undefined)
76	      || (typeof message.projectRef === 'string' && message.threadRef === undefined))
77	    && typeof message.messageRef === 'string' && typeof message.bodyDigest === 'string')) return undefined
78	  const activities = surface.activities
79	  if (activities !== undefined && (!Array.isArray(activities) || !activities.every(isSurfaceActivityBinding))) return undefined
80	  return { ...(surface as TeamMessageSurface), activities: (activities ?? []) as readonly SurfaceActivityBinding[] }
81	}
82	
83	function isSurfaceActivityBinding(value: unknown): value is SurfaceActivityBinding {
84	  if (typeof value !== 'object' || value === null) return false
85	  const item = value as { readonly scope?: unknown; readonly activityRef?: unknown; readonly threadRef?: unknown; readonly projectRef?: unknown; readonly factDigest?: unknown }
86	  if (typeof item.activityRef !== 'string' || typeof item.factDigest !== 'string') return false
87	  return (item.scope === 'thread' && typeof item.threadRef === 'string' && item.projectRef === undefined)
88	    || (item.scope === 'main' && typeof item.projectRef === 'string' && item.threadRef === undefined)
89	}
90	
91	export function isFactOnSurface(entries: readonly TeamMessageSurface[], fact: AgentTeamThreadReadFact, threadRef: AgentTeamThreadRef): boolean {
92	  if (fact.fact.kind === 'activity') {
93	    return fact.fact.activity.threadRef === threadRef && isActivityOnSurface(entries, activityFact(fact.fact.activity))
94	  }
95	  if (fact.fact.kind !== 'message' || fact.fact.message.body === '') return false
96	  const { messageRef, body } = fact.fact.message
97	  return missingMessageRange(entries, { threadRef, messageRef, body }) === undefined
98	}
99	
100	export function isMainEntryOnSurface(entries: readonly TeamMessageSurface[], entry: AgentTeamMainTimelineEntry, projectRef: AgentTeamProjectRef): boolean {
101	  if (entry.kind === 'activity') {
102	    return entry.activity.projectRef === projectRef && isActivityOnSurface(entries, activityFact(entry.activity))
103	  }
104	  if (entry.kind !== 'message' || entry.message.body === '') return false
105	  return missingMessageRange(entries, { projectRef, messageRef: entry.message.messageRef, body: entry.message.body }) === undefined
106	}
107	
108	/** A Command or Remote projection is not a Session output: only the bound activity text attests. */
109	export function isActivityOnSurface(entries: readonly TeamMessageSurface[], fact: ActivityFact): boolean {
110	  const identity = activityIdentity(fact)
111	  const factDigest = activityFactDigest(fact)
112	  return entries.some(entry => entry.activities.some(activity => activity.factDigest === factDigest
113	    && activity.activityRef === identity.activityRef
114	    && (identity.scope === 'thread'
115	      ? activity.scope === 'thread' && activity.threadRef === identity.threadRef
116	      : activity.scope === 'main' && activity.projectRef === identity.projectRef)))
117	}
118	
119	export function missingMessageRange(entries: readonly TeamMessageSurface[], target: RenderedTeamMessage): { start: number; end: number } | undefined {
120	  const bodyDigest = digest(target.body)
121	  const ranges = entries.flatMap(entry => entry.messages.filter(message => message.threadRef === target.threadRef
122	    && message.projectRef === target.projectRef && message.messageRef === target.messageRef && message.bodyDigest === bodyDigest)
123	    .flatMap(message => message.start === undefined && message.end === undefined && message.total === undefined
124	      ? [{ start: 0, end: target.body.length }]
125	      : Number.isInteger(message.start) && Number.isInteger(message.end) && message.total === target.body.length
126	        && message.start! >= 0 && message.end! > message.start! && message.end! <= target.body.length
127	        ? [{ start: message.start!, end: message.end! }] : []))
128	    .sort((left, right) => left.start - right.start)
129	  let start = 0
130	  for (const range of ranges) {
131	    if (range.start > start) return { start, end: range.start }
132	    start = Math.max(start, range.end)
133	  }
134	  return start >= target.body.length ? undefined : { start, end: target.body.length }
135	}
136	
137	export function surfaceVisibilityProbe(agentFor: (memberId: AgentTeamMemberId) => Agent | undefined) {
138	  return (memberId: AgentTeamMemberId, facts: readonly AgentTeamThreadReadFact[], threadRef: AgentTeamThreadRef): boolean => {
139	    const agent = agentFor(memberId)
140	    if (agent === undefined) return false
141	    const entries = visibleTeamSurface(agent)
142	    return facts.every(fact => isFactOnSurface(entries, fact, threadRef))
143	  }
144	}
