import { describe, expect, it } from 'vitest'
import { Session, SessionId } from '@deepseek-ai/dsh-session'
import { teamMessageSurface } from '@contexera/dsh-agent-team/host'
import { LlmError } from '@deepseek-ai/dsh-llm'
import { budgetReading, messagePartText, readingCapacity, type MessagePart } from '../src/reading-budget.ts'

/**
 * The pure selection core, tested without a Host. Integration suites cover the
 * same behaviour through real Sessions; these cases pin the arithmetic that is
 * awkward to reach there: capacity fallbacks, zero-length parts, and the
 * binary search's surrogate boundary.
 */

/** A Session carrying the tool/result and tool/call pairs `visibleTeamSurface` accepts. */
function surfaceWith(parts: readonly { start: number; end: number }[], body: string, messageRef = 'message:a') {
  const session = Session.create(SessionId('session:budget'))
  const text = `part ${parts.map(part => `${part.start}-${part.end}`).join(',')}`
  const callId = 'call:1'
  session.append('tool/call', { turn: 1, step: 1, callId, name: 'team_thread', arguments: '{}' })
  session.append('tool/result', { turn: 1, step: 1, callId, name: 'team_thread', isError: false, content: [{ type: 'text', text }],
    meta: { teamFacts: teamMessageSurface(text, parts.map(part => ({ threadRef: 'thread:t', messageRef, body, ...part, total: body.length }))) } })
  return session
}

const agentFor = (session: Session, options: { provider?: string; model?: string; contextWindow?: number } = {}) => ({
  session,
  options: { provider: options.provider, model: options.model },
  ctx: { get: () => options.contextWindow === undefined ? undefined : ({
    resolveModelInfo: async () => ({ context: { contextWindow: options.contextWindow } }),
  }) },
}) as never

const readValue = (facts: readonly { sequence: number; body: string; unread: boolean }[]) => ({
  projectRef: 'project:p', threadRef: 'thread:t', kind: 'read',
  facts: facts.map(fact => ({ sequence: fact.sequence, kind: 'message', messageRef: `message:${fact.sequence}`, body: fact.body, unread: fact.unread })),
  remainingUnreadCount: 0,
})

const render = (value: unknown): string => JSON.stringify(value)

describe('messagePartText', () => {
  it('renders the whole body when there is no part', () => {
    expect(messagePartText('body', undefined)).toBe('body')
  })

  it('names the range and whether the context now holds the whole body', () => {
    expect(messagePartText('abcdef', { messageRef: 'message:a', start: 0, end: 3, complete: false }))
      .toBe('Message part 0–3 of 6 — incomplete; not acknowledged\n<message-part ref="message:a" start="0" end="3">\nabc\n</message-part>')
    expect(messagePartText('abcdef', { messageRef: 'message:a', start: 3, end: 6, complete: true }))
      .toContain('Message part 3–6 of 6 — complete in current context')
  })
})

describe('readingCapacity', () => {
  it('falls back to the conservative limit when nothing resolves the model', async () => {
    await expect(readingCapacity(agentFor(surfaceWith([], '')), new AbortController().signal)).resolves.toBe(256 * 1024)
  })

  it('falls back rather than failing when model metadata is unusable', async () => {
    const agent = { session: surfaceWith([], ''), options: { provider: 'p', model: 'm' },
      ctx: { get: () => ({ resolveModelInfo: async () => { throw new LlmError('bad', { code: 'INVALID_MODEL_INFO' }) } }) } } as never
    await expect(readingCapacity(agent, new AbortController().signal)).resolves.toBe(256 * 1024)
  })

  it('surfaces the caller’s own abort', async () => {
    const agent = { session: surfaceWith([], ''), options: { provider: 'p', model: 'm' },
      ctx: { get: () => ({ resolveModelInfo: async () => { throw new LlmError('aborted', { code: 'ABORTED' }) } }) } } as never
    await expect(readingCapacity(agent, new AbortController().signal)).rejects.toThrow()
  })

  it('derives the window from the model and reserves the completion headroom', async () => {
    await expect(readingCapacity(agentFor(surfaceWith([], ''), { provider: 'p', model: 'm', contextWindow: 200_000 }), new AbortController().signal))
      .resolves.toBe(200_000 - 16_384)
  })
})

describe('budgetReading', () => {
  const body = 'x'.repeat(40_000)

  it('acknowledges nothing when the first unread Message is incomplete', () => {
    const agent = agentFor(surfaceWith([], body))
    const result = budgetReading(agent, readValue([{ sequence: 1, body, unread: true }]), render, 256 * 1024)
    expect(result.through).toBe(0)
    expect(result.value.messageParts?.[0]).toMatchObject({ complete: false })
  })

  it('acknowledges the last fact it could deliver in full', () => {
    const agent = agentFor(surfaceWith([], 'short'))
    const result = budgetReading(agent, readValue([{ sequence: 1, body: 'short', unread: true }]), render, 256 * 1024)
    expect(result.through).toBe(1)
    expect(result.value.messageParts).toEqual([])
  })

  it('renders no zero-length part once the whole body is already on the surface', () => {
    const agent = agentFor(surfaceWith([{ start: 0, end: body.length }], body))
    const result = budgetReading(agent, readValue([{ sequence: 1, body, unread: true }]), render, 256 * 1024)
    expect(result.value.messageParts).toEqual([])
    expect(result.value.facts?.[0]).toMatchObject({ bodyOmitted: true })
  })

  it('never splits a surrogate pair at a part boundary', () => {
    // A lone high surrogate at the candidate boundary must move the end back by
    // one, so no part ever renders half of one emoji.
    const pair = '🙂'.repeat(20_000)
    const agent = agentFor(surfaceWith([], pair))
    const result = budgetReading(agent, readValue([{ sequence: 1, body: pair, unread: true }]), render, 256 * 1024)
    const part = result.value.messageParts![0]!
    expect(pair[part.end - 1]).not.toMatch(/[\uD800-\uDBFF]/)
  })

  it('refuses a Message beyond the model capacity without acknowledging it', () => {
    const agent = agentFor(surfaceWith([], body))
    expect(() => budgetReading(agent, readValue([{ sequence: 1, body, unread: true }]), render, 1000))
      .toThrow(/exceeds the reading capacity/)
  })
})

